// Solid street-side volumes, mixed-use blocks, capture scene and original instrumental score.
const districtSheet=new Image(),caughtGroup=new Image();let districtReady=false,caughtReady=false;
districtSheet.onload=()=>districtReady=true;districtSheet.src='assets/saigon-neighborhood.webp';caughtGroup.onload=()=>caughtReady=true;caughtGroup.src='assets/vy-caught.webp';
const districtKinds=['apartment','house','cafe','park','food','townhouse','park','modern'];
const districtHeights={apartment:11,house:3.2,cafe:5,food:3.2,townhouse:7.8,modern:14.5,park:0};
function districtLots(){const out=[],travel=worldDistance*.4,total=216;for(let i=0;i<12;i++){const raw=((i*18-travel)%total+total)%total-18,far=raw+16;if(far<4||raw>140)continue;for(const side of [-1,1]){const kind=districtKinds[(i+(side>0?3:0))%districtKinds.length];out.push({side,index:i,kind,rawNear:raw,near:Math.max(3.5,raw),far,height:districtHeights[kind]})}}return out.sort((a,b)=>b.far-a.far)}
function face(points,color){poly(points.map(p=>[p.x,p.y]),color)}
function solidBox(x0,x1,z0,z1,height,colors,base=0){const a=streetPoint(x0,z0,base),b=streetPoint(x1,z0,base),c=streetPoint(x1,z1,base),d=streetPoint(x0,z1,base),A=streetPoint(x0,z0,base+height),B=streetPoint(x1,z0,base+height),C=streetPoint(x1,z1,base+height),D=streetPoint(x0,z1,base+height);face([a,b,B,A],colors[1]);face([d,c,C,D],colors[2]||colors[1]);if(base+height<6)face([A,B,C,D],colors[2]||'#e4d5bd');face(x0<0?[b,c,C,B]:[a,d,D,A],colors[0]);return{a,b,c,d,A,B,C,D}}
function textureDistrict(b,cell){if(!districtReady)return;const cw=districtSheet.width/3,ch=districtSheet.height/2,sx=(cell%3)*cw,sy=Math.floor(cell/3)*ch,x=b.side*1.5,steps=b.near<30?6:b.near<70?3:1;for(let i=0;i<steps;i++){const z0=b.near+(b.far-b.near)*i/steps,z1=b.near+(b.far-b.near)*(i+1)/steps,u0=(z0-b.rawNear)/16,u1=(z1-b.rawNear)/16;const src=[{x:sx+u0*cw,y:sy+ch},{x:sx+u1*cw,y:sy+ch},{x:sx+u1*cw,y:sy},{x:sx+u0*cw,y:sy}],dst=[streetPoint(x,z0),streetPoint(x,z1),streetPoint(x,z1,b.height),streetPoint(x,z0,b.height)];imageTriangle(districtSheet,[src[0],src[1],src[2]],[dst[0],dst[1],dst[2]]);imageTriangle(districtSheet,[src[0],src[2],src[3]],[dst[0],dst[2],dst[3]])}}
function endWallWindows(b,x0,x1){if(b.rawNear<3.5)return;if(districtReady){const cell={apartment:0,house:1,cafe:2,food:3,modern:4,townhouse:5}[b.kind],cw=districtSheet.width/3,ch=districtSheet.height/2,sx=cell%3*cw,sy=Math.floor(cell/3)*ch,src=[{x:sx+cw*.15,y:sy+ch*.97},{x:sx+cw*.85,y:sy+ch*.97},{x:sx+cw*.85,y:sy+ch*.04},{x:sx+cw*.15,y:sy+ch*.04}],dst=[streetPoint(x0,b.near),streetPoint(x1,b.near),streetPoint(x1,b.near,b.height),streetPoint(x0,b.near,b.height)];imageTriangle(districtSheet,[src[0],src[1],src[2]],[dst[0],dst[1],dst[2]]);imageTriangle(districtSheet,[src[0],src[2],src[3]],[dst[0],dst[2],dst[3]]);return}for(let floor=0;floor<Math.floor(b.height/2.8);floor++)for(let win=0;win<2;win++){const xa=x0+(x1-x0)*(.17+win*.4),xb=xa+(x1-x0)*.23,y=.9+floor*2.8;face([streetPoint(xa,b.near,y),streetPoint(xb,b.near,y),streetPoint(xb,b.near,y+1.2),streetPoint(xa,b.near,y+1.2)],rain>.3?'#d3b77d':'#477483')}}
function tiledRoof(b,x0,x1){if(b.height>=6)return;const mid=(x0+x1)/2,ha=b.height,hr=ha+.9;face([streetPoint(x0,b.near,ha),streetPoint(mid,b.near,hr),streetPoint(mid,b.far,hr),streetPoint(x0,b.far,ha)],'#b97359');face([streetPoint(mid,b.near,hr),streetPoint(x1,b.near,ha),streetPoint(x1,b.far,ha),streetPoint(mid,b.far,hr)],'#8e594f');face([streetPoint(x0,b.near,ha),streetPoint(x1,b.near,ha),streetPoint(mid,b.near,hr)],'#d39f77');ctx.strokeStyle='#e3b28c88';ctx.lineWidth=1;for(let i=1;i<9;i++){const z=b.near+(b.far-b.near)*i/9,a=streetPoint(x0,z,ha),c=streetPoint(mid,z,hr);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(c.x,c.y);ctx.stroke()}}
function seatedPatron(x,Z,color){const p=streetPoint(x,Z),H=heroSize()*.66*p.s;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#5e4d43';ctx.fillRect(-H*.17,-H*.31,H*.34,H*.07);ctx.fillRect(-H*.15,-H*.24,H*.04,H*.24);ctx.fillRect(H*.11,-H*.24,H*.04,H*.24);ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-H*.43,H*.17,H*.23,0,0,7);ctx.fill();ctx.fillStyle='#dfb99d';ctx.beginPath();ctx.arc(0,-H*.76,H*.19,0,7);ctx.fill();ctx.fillStyle='#3c3440';ctx.beginPath();ctx.ellipse(0,-H*.83,H*.20,H*.13,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#263946';ctx.beginPath();ctx.arc(-H*.06,-H*.77,Math.max(1,H*.015),0,7);ctx.arc(H*.06,-H*.77,Math.max(1,H*.015),0,7);ctx.fill();ctx.strokeStyle='#3a4350';ctx.lineWidth=H*.07;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-H*.09,-H*.28);ctx.lineTo(-H*.1,-H*.04);ctx.moveTo(H*.08,-H*.28);ctx.lineTo(H*.1,-H*.04);ctx.stroke();ctx.restore()}
function cafePatio(b){const side=b.side;for(let j=0;j<2;j++){const Z=b.near+4+j*6;if(Z>b.far-1)continue;const p=streetPoint(side*1.24,Z),s=p.s,H=heroSize();ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle='#675548';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-H*.32*s);ctx.stroke();ctx.fillStyle='#ae815d';ctx.beginPath();ctx.ellipse(0,-H*.32*s,H*.18*s,H*.07*s,0,0,7);ctx.fill();ctx.fillStyle='#e7e0ce';ctx.fillRect(-5*s,-H*.39*s,8*s,10*s);ctx.strokeStyle='#eee6cb88';ctx.lineWidth=s;ctx.beginPath();ctx.moveTo(0,-H*.41*s);ctx.quadraticCurveTo(6*s,-H*.46*s,0,-H*.50*s);ctx.stroke();ctx.restore()}}
function parkTree(x,Z,shade){const p=streetPoint(x,Z),s=p.s,H=canvas.clientHeight*.34;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#8a7058';ctx.fillRect(-5*s,-H*.65*s,10*s,H*.65*s);const g=ctx.createRadialGradient(0,-H*.75*s,2,-H*.1*s,-H*.7*s,H*.5*s);g.addColorStop(0,shade);g.addColorStop(1,'#345f4d');ctx.fillStyle=g;for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(Math.sin(i*2)*H*.14*s,-H*(.58+i*.1)*s,H*.24*s,H*.27*s,0,0,7);ctx.fill()}ctx.restore()}
function renderPark(b){const s=b.side,x0=s*1.12,x1=s*2.75;face([streetPoint(x0,b.near),streetPoint(x1,b.near),streetPoint(x1,b.far),streetPoint(x0,b.far)],'#6e9b6d');face([streetPoint(s*1.17,b.near+1),streetPoint(s*1.45,b.near+1),streetPoint(s*2.5,b.far-1),streetPoint(s*2.25,b.far-1)],'#d8c6a1');for(let j=0;j<4;j++)parkTree(s*(1.6+(j%2)*.7),b.far-2-j*3,j%2?'#94b77d':'#80a66f');const mid=(b.near+b.far)/2,p=streetPoint(s*2.05,mid);ctx.fillStyle='#c4cbc0';ctx.beginPath();ctx.ellipse(p.x,p.y,45*p.s,15*p.s,0,0,7);ctx.fill();ctx.fillStyle='#80bbc2';ctx.beginPath();ctx.ellipse(p.x,p.y-3*p.s,35*p.s,10*p.s,0,0,7);ctx.fill();ctx.strokeStyle='#c7e7e0';ctx.lineWidth=2*p.s;ctx.beginPath();ctx.moveTo(p.x,p.y-3*p.s);ctx.quadraticCurveTo(p.x+8*p.s,p.y-55*p.s,p.x-6*p.s,p.y-8*p.s);ctx.stroke();solidBox(s*1.5,s*1.9,b.near+3,b.near+4,.3,['#aa835f','#8c6b50','#c8a47a'],.4);seatedPatron(s*1.7,b.near+3.5,'#d6a382')}
renderFacades=function(){const colors={apartment:['#b4c9c2','#7f9b98','#ccd4c2'],house:['#d5bc94','#a58b70','#e4d3af'],cafe:['#87aaa5','#5e8585','#b1c8bc'],food:['#d0a079','#a77c5d','#e1bb8e'],townhouse:['#d7c39b','#a6977e','#e4d9bd'],modern:['#a7bec2','#6f8b99','#d3ded7']};for(const b of districtLots()){if(b.kind==='park'){renderPark(b);continue}const x0=b.side*1.5,x1=b.side*2.8;solidBox(Math.min(x0,x1),Math.max(x0,x1),b.near,b.far,b.height,colors[b.kind]);endWallWindows(b,Math.min(x0,x1),Math.max(x0,x1));textureDistrict(b,{apartment:0,house:1,cafe:2,food:3,modern:4,townhouse:5}[b.kind]);tiledRoof(b,Math.min(x0,x1),Math.max(x0,x1));if(b.kind==='cafe'||b.kind==='food')cafePatio(b)}};
let captureTime=-1;
const districtStart=start,districtFinish=finish,districtFrame=frame,districtDraw=draw,districtLate=enterLateEnding,districtRetry=retryBoss;
start=function(){captureTime=-1;scoreCompleted='';stopScore(true);districtStart();prepareScores()};
retryBoss=function(){captureTime=-1;stopScore(true);districtRetry()};
enterLateEnding=function(){districtLate();if(lateEnding===0){captureTime=0;$('chapterTitle').textContent='Bị bắt kịp mất rồi…';$('bubble').hidden=true}};
function drawCaught(){const w=canvas.clientWidth,h=canvas.clientHeight;weatherPanel(rain>.4?1:0,w,h);ctx.fillStyle='#101e38a6';ctx.fillRect(0,0,w,h);if(caughtReady){const scale=Math.min(w*.94/caughtGroup.width,h*.67/caughtGroup.height)*(1+Math.min(.04,captureTime*.008)),W=caughtGroup.width*scale,H=caughtGroup.height*scale;ctx.drawImage(caughtGroup,(w-W)/2,h*.83-H,W,H)}else{sprite(5,w*.5,h*.82,heroSize()*1.5);drawPursuers()}ctx.fillStyle='#0c1a2be8';ctx.fillRect(0,0,w,h*.19);text('SẾP · DEADLINE · BẢN KẾ HOẠCH ĐÃ BẮT KỊP',w/2,h*.075,Math.max(9,Math.min(14,w/48)),'#efbc9b');text('Vy buồn bã nhìn đồng hồ… Nhưng hôm nay, Vy được về nhà.',w/2,h*.14,Math.max(8,Math.min(12,w/58)),'#e5d5c7')}
draw=function(){if(captureTime>=0&&captureTime<4.8){drawCaught();return}districtDraw()};
frame=function(t){if(captureTime>=0&&captureTime<4.8&&playing){const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!paused){captureTime+=dt;elapsed+=dt}draw();syncScore();if(captureTime>=4.8){captureTime=-1;$('chapterTitle').textContent='Chậm một nhịp thôi. Vẫn có người đang chờ.'}raf=requestAnimationFrame(frame);return}districtFrame(t);syncScore()};
finish=function(){districtFinish();syncScore()};
// Original recorded instrumental cues, decoded through the gesture-unlocked AudioContext.
const scoreFiles={emotion:'score-emotion.mp3',courage:'score-courage.mp3',birthday:'score-birthday.mp3'},scoreBuffers={},scoreBytes={};
for(const [key,file] of Object.entries(scoreFiles))scoreBytes[key]=fetch('assets/'+file).then(r=>r.arrayBuffer()).catch(()=>null);
let scoreKey='',scoreSource=null,scoreGain=null,scoreOffset=0,scoreStarted=0,scoreCompleted='',scorePreparing=false;
function scoreIntent(){if(captureTime>=0)return'emotion';if(playing&&lateEnding>=0)return lateEnding>=21?'birthday':lateEnding<15?'emotion':'';if(playing&&combatResult==='lost')return rescueTime>=9?'birthday':'emotion';if(playing&&epilogue>=0)return epilogue<11?'emotion':'courage';if(!playing&&!$('finish').hidden)return'birthday';return''}
function prepareScores(){if(!audio||scorePreparing)return;scorePreparing=true;for(const key of Object.keys(scoreFiles))scoreBytes[key].then(b=>b&&audio.decodeAudioData(b.slice(0))).then(b=>{if(b)scoreBuffers[key]=b}).catch(()=>{})}
function stopScore(reset=false){if(scoreSource){scoreOffset+=Math.max(0,audio.currentTime-scoreStarted);scoreSource.onended=null;try{scoreSource.stop()}catch{}scoreSource=null}if(scoreGain){try{scoreGain.disconnect()}catch{}scoreGain=null}if(reset){scoreKey='';scoreOffset=0;scoreCompleted=''}}
function startScore(key){if(!audio||!scoreBuffers[key]||scoreCompleted===key)return;const buffer=scoreBuffers[key],source=audio.createBufferSource(),gain=audio.createGain();source.buffer=buffer;source.loop=key!=='birthday';source.connect(gain);gain.connect(audio.destination);gain.gain.setValueAtTime(0,audio.currentTime);gain.gain.linearRampToValueAtTime(key==='birthday'?.42:.30,audio.currentTime+.6);scoreSource=source;scoreGain=gain;scoreStarted=audio.currentTime;source.onended=()=>{if(scoreSource===source){scoreCompleted=key;scoreSource=null}};source.start(0,source.loop?scoreOffset%buffer.duration:Math.min(scoreOffset,buffer.duration-.01))}
function syncScore(){const key=scoreIntent();if(key!==scoreKey){stopScore();scoreKey=key;scoreOffset=0;scoreCompleted=''}if(!sound||paused||!key){stopScore();return}if(!scoreSource)startScore(key)}
const scoredSoundClick=$('sound').onclick;$('sound').onclick=()=>{scoredSoundClick();prepareScores();syncScore()};const scoredPauseClick=$('pause').onclick;$('pause').onclick=()=>{scoredPauseClick();syncScore()};
playLateSong=function(){lateMusic=lateEnding>=21};playRescueSong=function(){};
